1045	/// A live (or frozen) amplitude-bar waveform. `amplitudeStream == null`
1046	/// renders a static placeholder pattern at [opacity] instead of
1047	/// subscribing — the "frozen" rendering `_AudioProcessingView` uses.
1048	class _Waveform extends StatefulWidget {
1049	  const _Waveform({required this.amplitudeStream, required this.opacity});
1050	
1051	  final Stream<double>? amplitudeStream;
1052	  final double opacity;
1053	
1054	  @override
1055	  State<_Waveform> createState() => _WaveformState();
1056	}
1057	
1058	class _WaveformState extends State<_Waveform> {
1059	  // `growable: true` — `build()` below reads this with `removeAt`/`add`
1060	  // on every new amplitude sample, which `List.filled`'s own default
1061	  // fixed-length list doesn't support.
1062	  final List<double> _samples = List.filled(
1063	    _waveformBarCount,
1064	    0.1,
1065	    growable: true,
1066	  );
1067	  StreamSubscription<double>? _subscription;
1068	
1069	  @override
1070	  void initState() {
1071	    super.initState();
1072	    _subscription = widget.amplitudeStream?.listen(
1073	      (amplitude) {
1074	        if (!mounted) {
1075	          return;
1076	        }
1077	        setState(() {
1078	          _samples.removeAt(0);
1079	          // `num.clamp` returns `num`, not `double` — `_samples` is
1080	          // `List<double>`.
1081	          _samples.add(amplitude.clamp(0.1, 1.0).toDouble());
1082	        });
1083	      },
1084	      // Review finding: an unhandled `onError` turns a native amplitude-
1085	      // stream error into an uncaught async exception — the waveform
1086	      // just stays frozen on its last sample instead, no worse than the
1087	      // already-handled "no live stream" (frozen/processing) case.
1088	      onError: (_) {},
1089	    );
1090	  }
1091	
1092	  @override
1093	  void dispose() {
1094	    _subscription?.cancel();
1095	    super.dispose();
1096	  }
1097	
1098	  @override
1099	  Widget build(BuildContext context) {
1100	    return Opacity(
1101	      opacity: widget.opacity,
1102	      child: SizedBox(
1103	        height: DesignTokens.spacing2xl,
1104	        child: Row(
1105	          mainAxisAlignment: MainAxisAlignment.center,
1106	          crossAxisAlignment: CrossAxisAlignment.center,
1107	          children: [
1108	            for (var i = 0; i < _samples.length; i++) ...[
1109	              AnimatedContainer(
1110	                duration: DesignTokens.durationSheetUp,
1111	                width: DesignTokens.spacingXs,
1112	                height: DesignTokens.spacing2xl * _samples[i],
1113	                decoration: const BoxDecoration(
1114	                  color: DesignTokens.colorError,
1115	                  borderRadius: BorderRadius.all(
1116	                    Radius.circular(DesignTokens.radiusFull),
1117	                  ),
1118	                ),
1119	              ),
1120	              if (i < _samples.length - 1)
1121	                const SizedBox(width: DesignTokens.spacingXs),
1122	            ],
1123	          ],
1124	        ),
1125	      ),
1126	    );
1127	  }
1128	}
