76	/// A save attempt from [AudioTranscribed] succeeded — `InsertionModal`'s
77	/// listener reacts to this exactly like `TextEntrySaved` (announce, then
78	/// pop). Terminal, same rationale as `TextEntrySaved`'s own doc.
79	class AudioSaved extends AudioCaptureState {
80	  const AudioSaved();
81	}
82	
83	/// The last attempt failed — covers all 3 failure rows of the I/O matrix:
84	/// - Mic permission denied -> [path]/[durationSeconds] both `null` ("No
85	///   file to preserve"); [AudioEntryCubit.retry] re-requests permission.
86	/// - Transcription failed -> [path]/[durationSeconds] carry the preserved
87	///   file; [AudioEntryCubit.retry] re-transcribes it, never re-records.
88	/// - Save failed (incl. offline) -> same preserved [path]/
89	///   [durationSeconds]/[text] semantics as `TextEntryError`; the modal's
90	///   `_AudioTab` keeps showing the editable text with Salvar re-enabled
91	///   rather than routing back through [AudioEntryCubit.retry].
92	class AudioError extends AudioCaptureState {
93	  const AudioError({
94	    required this.path,
95	    required this.durationSeconds,
96	    required this.message,
97	    this.text,
98	  });
99	
100	  final String? path;
101	  final int? durationSeconds;
102	  final String message;
103	
104	  /// Non-null only for a save failure — lets `_AudioTab` keep rendering
105	  /// the editable text field under the inline error, same as
106	  /// `TextEntryError`'s own `_TextoTab` rendering.
107	  final String? text;
108	}
109	
110	/// Drives the Áudio tab's recording -> processing -> transcribed/error
111	/// pipeline (Intent). A fresh, `get_it`-factory-scoped instance per "+"
112	/// tap, same convention as `TextEntryCubit` — [MicRecorder]/
113	/// [AudioTranscriber] themselves stay long-lived `get_it` singletons
114	/// (`capture_injection.dart`), shared across every modal open the way
115	/// `EntriesRepository` already is for `TextEntryCubit`.
116	class AudioEntryCubit extends Cubit<AudioCaptureState> {
117	  AudioEntryCubit(this._micRecorder, this._audioTranscriber, this._repository)
118	    : super(const AudioIdle());
119	
120	  final MicRecorder _micRecorder;
121	  final AudioTranscriber _audioTranscriber;
122	  final EntriesRepository _repository;
123	
124	  Timer? _elapsedTimer;
125	
126	  /// Bumped by [cancel] so an in-flight [startRecording]/[stopRecording]
127	  /// continuation can tell "the user already left the Áudio tab while I
128	  /// was awaiting" apart from "nothing has changed since I started" —
129	  /// the same role `isClosed` already plays for `close()`, but for a tab
130	  /// switch that doesn't close the cubit itself (Review finding: without
131	  /// this, `cancel()` running mid-await either left the recorder running
132	  /// unobserved, or let a stale `stop()`/transcription result resurrect a
133	  /// flow the user already left).
134	  int _generation = 0;
135	
136	  /// Guards [stopRecording] against a second concurrent call (e.g. a fast
137	  /// double-tap on the stop control before the UI rebuilds past
138	  /// [AudioRecording]) — without this, a second `_micRecorder.stop()` call
139	  /// racing the first could return `null` (nothing left to stop) and
140	  /// overwrite a perfectly good [AudioProcessing]/transcription result
141	  /// with a bogus [AudioError] (Review finding).
142	  bool _stopping = false;
143	
144	  /// Forwarded straight from [MicRecorder.amplitudeStream] — lets
145	  /// `_AudioTab`'s waveform animate without ever importing `package:record`
146	  /// itself (Boundaries).
147	  Stream<double> get amplitudeStream => _micRecorder.amplitudeStream;
148	
149	  /// Starts recording — called from `InsertionModal`'s tab-switch
150	  /// listener the instant the Áudio tab becomes active (Acceptance
151	  /// Criteria: "recording starts immediately"), and again by [retry] when
152	  /// the last attempt failed before any file ever existed (permission
153	  /// denied). Ignored while a recording is already in progress, and —
154	  /// Review finding — ignored once the pipeline has moved past recording
155	  /// ([AudioProcessing]/[AudioTranscribed]/an [AudioError] that still
156	  /// carries a file): without this, re-entering the Áudio tab after a
157	  /// completed transcription silently discarded the transcribed text and
158	  /// started a brand-new recording over it. Only [AudioIdle] (fresh) or
159	  /// an [AudioError] with no file (nothing to discard) actually start.
160	  Future<void> startRecording() async {
161	    final current = state;
162	    final canStart =
163	        current is AudioIdle ||
164	        (current is AudioError && current.path == null);
165	    if (!canStart) {
166	      return;
167	    }
168	    final generation = ++_generation;
169	    bool hasPermission;
170	    try {
171	      hasPermission = await _micRecorder.hasPermission();
172	    } catch (_) {
173	      // Review finding: a thrown `PlatformException` (native-side error)
174	      // must never escape uncaught — surfaces through the same
175	      // error/retry path as a plain permission denial.
176	      if (isClosed || generation != _generation) {
177	        return;
178	      }
179	      emit(
180	        const AudioError(
181	          path: null,
182	          durationSeconds: null,
183	          message: 'Não foi possível acessar o microfone.',
184	        ),
185	      );
186	      return;
187	    }
188	    if (isClosed || generation != _generation) {
189	      return;
190	    }
191	    if (!hasPermission) {
192	      emit(
193	        const AudioError(
194	          path: null,
195	          durationSeconds: null,
196	          message:
197	              'Permissão de microfone negada. Toque em "Tentar novamente" '
198	              'para permitir o acesso.',
199	        ),
200	      );
201	      return;
202	    }
203	    try {
204	      await _micRecorder.start();
205	    } catch (_) {
206	      // Review finding: same rationale as the `hasPermission()` catch
207	      // above — a native-side start failure must surface through the
208	      // normal error/retry path instead of escaping uncaught.
209	      if (isClosed || generation != _generation) {
210	        // Review finding: the shared `_micRecorder` singleton may already
211	        // belong to a newer, currently-active generation by the time this
212	        // stale catch fires — never release it from here, only from the
213	        // generation that's still actually live, or this would silently
214	        // kill a different, active recording with no error surfaced.
215	        return;
216	      }
217	      // Also releases the native recorder best-effort (Review finding): a
218	      // partial/failed `start()` may still have left a session open.
219	      unawaited(_safeCancelRecorder());
220	      emit(
221	        const AudioError(
222	          path: null,
223	          durationSeconds: null,
224	          message: 'Não foi possível iniciar a gravação.',
225	        ),
226	      );
227	      return;
228	    }
229	    if (isClosed || generation != _generation) {
230	      // Review finding: `cancel()` bumped `_generation` (the user already
231	      // left the Áudio tab) while `start()` was in flight — stop/discard
232	      // the session we just started instead of leaving a live, unobserved
233	      // recording running.
234	      unawaited(_safeCancelRecorder());
235	      return;
236	    }
237	    _startElapsedTimer();
238	    emit(const AudioRecording(elapsedSeconds: 0));
239	  }
240	
241	  void _startElapsedTimer() {
242	    _elapsedTimer?.cancel();
243	    var elapsed = 0;
244	    _elapsedTimer = Timer.periodic(const Duration(seconds: 1), (_) {
245	      elapsed++;
246	      if (state is AudioRecording) {
247	        emit(AudioRecording(elapsedSeconds: elapsed));
248	      }
249	    });
250	  }
251	
252	  /// Stops recording and immediately kicks off transcription — the I/O
253	  /// matrix's "Happy path"/"Transcription fails" rows. Ignored outside
254	  /// [AudioRecording] (e.g. a stray second tap on the stop control) and
255	  /// — Review finding — ignored while a previous call is still awaiting
256	  /// `_micRecorder.stop()` ([_stopping]): without this, a fast double-tap
257	  /// on the stop control could fire a second `_micRecorder.stop()` call
258	  /// that returns `null` (nothing left to stop) and clobber the first
259	  /// call's genuine result with a bogus `AudioError`.
260	  Future<void> stopRecording() async {
261	    if (state is! AudioRecording || _stopping) {
262	      return;
263	    }
264	    _stopping = true;
265	    final generation = _generation;
266	    _elapsedTimer?.cancel();
267	    MicRecording? recording;
268	    try {
269	      recording = await _micRecorder.stop();
270	    } catch (_) {
271	      // Review finding: a thrown `PlatformException` must never escape
272	      // uncaught — surfaces through the normal error/retry path instead.
273	      _stopping = false;
274	      if (isClosed || generation != _generation) {
275	        // Review finding: the shared `_micRecorder` singleton may already
276	        // belong to a newer, currently-active generation by the time this
277	        // stale catch fires — never release it from here, only from the
278	        // generation that's still actually live, or this would silently
279	        // kill a different, active recording with no error surfaced.
280	        return;
281	      }
282	      // Also releases the native recorder best-effort (Review finding): a
283	      // failed `stop()` leaves the actual native session state
284	      // unconfirmed, so this is the only chance to try to release it.
285	      unawaited(_safeCancelRecorder());
286	      emit(
287	        const AudioError(
288	          path: null,
289	          durationSeconds: null,
290	          message: 'Não foi possível gravar o áudio.',
291	        ),
292	      );
293	      return;
294	    }
295	    _stopping = false;
296	    // Review finding: without the `_generation` check, a `cancel()` that
297	    // ran while `_micRecorder.stop()` was in flight (tab switch right
298	    // after tapping stop) already reset the cubit to `AudioIdle` — this
299	    // continuation must not resurrect the flow with a stale
300	    // `AudioProcessing`/`AudioError` emission on top of that reset.
301	    if (isClosed || generation != _generation) {
302	      return;
303	    }
304	    if (recording == null) {
305	      // Stopped with nothing actually captured — the I/O matrix has no
306	      // dedicated row for this (it should be unreachable in practice: the
307	      // recorder was just started above), but `AudioError` with no file
308	      // still gives the user a path back in via retry's permission-
309	      // re-request branch rather than leaving the cubit stuck mid-flow.
310	      emit(
311	        const AudioError(
312	          path: null,
313	          durationSeconds: null,
314	          message: 'Não foi possível gravar o áudio.',
315	        ),
316	      );
317	      return;
318	    }
319	    emit(
320	      AudioProcessing(
321	        path: recording.path,
322	        durationSeconds: recording.durationSeconds,
323	      ),
324	    );
325	    await _transcribe(recording.path, recording.durationSeconds);
326	  }
327	
328	  Future<void> _transcribe(String path, int durationSeconds) async {
329	    final text = await _audioTranscriber.transcribe(path);
330	    if (isClosed) {
331	      return;
332	    }
333	    // Guards a tab switch away mid-processing (`cancel()`, below) that
334	    // already reset the state to `AudioIdle` by the time this resolves —
335	    // without this, the eventual transcription result would still land
336	    // and resurrect a flow the user already left.
337	    if (state is! AudioProcessing ||
338	        (state as AudioProcessing).path != path) {
339	      return;
340	    }
341	    if (text == null) {
342	      emit(
343	        AudioError(
344	          path: path,
345	          durationSeconds: durationSeconds,
346	          message: 'Não foi possível transcrever o áudio.',
347	        ),
348	      );
349	      return;
350	    }
351	    emit(
352	      AudioTranscribed(
353	        path: path,
354	        durationSeconds: durationSeconds,
355	        text: text,
356	        saving: false,
357	      ),
358	    );
359	  }
360	
361	  /// "Tentar novamente" — re-requests permission when no file was ever
362	  /// recorded, or re-transcribes the same preserved file otherwise (I/O
363	  /// matrix: never re-records, never auto-retries on its own). A no-op
364	  /// outside [AudioError], or for a save failure (non-null [AudioError.
365	  /// text]) — that case's own retry is just tapping Salvar again, handled
366	  /// by [save] directly, not this method.
367	  Future<void> retry() async {
368	    final current = state;
369	    if (current is! AudioError || current.text != null) {
370	      return;
371	    }
372	    final path = current.path;
373	    final durationSeconds = current.durationSeconds;
374	    if (path == null || durationSeconds == null) {
375	      await startRecording();
376	      return;
377	    }
378	    emit(AudioProcessing(path: path, durationSeconds: durationSeconds));
379	    await _transcribe(path, durationSeconds);
380	  }
381	
382	  /// Mirrors the Texto field's own `updateText` — keeps the transcribed
383	  /// text editable before Salvar (Acceptance Criteria). Ignored while a
384	  /// save is already in flight, same rationale as `TextEntryCubit.
385	  /// updateText`.
386	  void updateText(String text) {
387	    final current = state;
388	    if (current is AudioTranscribed && !current.saving) {
389	      emit(current.copyWith(text: text));
390	    } else if (current is AudioError && current.text != null) {
391	      // Review finding: a save failure (`AudioError` with non-null
392	      // `text`) renders the same editable field as `AudioTranscribed`
393	      // (`_AudioErrorView`'s non-retry branch) — without this branch,
394	      // typing there updated the `TextField`'s own controller visually
395	      // but never the cubit's record of the text, so a retried `save()`
396	      // would silently resend the stale pre-failure text.
397	      emit(
398	        AudioError(
399	          path: current.path,
400	          durationSeconds: current.durationSeconds,
401	          message: current.message,
402	          text: text,
403	        ),
404	      );
405	    }
406	  }
407	
408	  /// Called when the Áudio tab loses focus mid-recording/mid-processing
409	  /// (`InsertionModal`'s tab-switch listener) — the I/O matrix's "Leave
410	  /// tab mid-recording" row: stops/releases the recorder, no `create()`
411	  /// ever fires. A no-op for every other state when [discardPreserved] is
412	  /// `false` (the default) — in particular [AudioTranscribed]/[AudioError],
413	  /// where the Never clause's trivial scope (resource safety only, not
414	  /// full Story 3.4 cancel-safety) means a tab switch must preserve the
415	  /// result rather than discard it.
416	  ///
417	  /// [discardPreserved] — Review finding: `InsertionModal.show()`'s
418	  /// `finally` also calls this (before `close()`) when the *whole modal*
419	  /// is dismissed (✕/swipe-down/barrier tap), not just the tab. In that
420	  /// case there's no "switch back to the tab later" to preserve for —
421	  /// the cubit is about to be closed — so a preserved [AudioTranscribed]
422	  /// or file-carrying [AudioError]'s temp file would otherwise never be
423	  /// cleaned up and leak on disk forever. Pass `true` only from that
424	  /// call site.
425	  Future<void> cancel({bool discardPreserved = false}) async {
426	    // Bumped unconditionally — including when the state below doesn't
427	    // match either branch — so an in-flight `startRecording()`/
428	    // `stopRecording()` continuation still sees the mismatch and aborts
429	    // itself (Review finding: previously only invalidated a flow already
430	    // visible in `state`, missing the window while those methods were
431	    // still awaiting).
432	    _generation++;
433	    // Review finding: without this, a hung `_micRecorder.stop()` call
434	    // (one that never resolves) left `_stopping` stuck `true` forever —
435	    // `stopRecording()`'s own guard made it a permanent no-op for the
436	    // rest of this cubit's life. The `_generation` bump above already
437	    // makes that stale continuation's eventual result a no-op, so
438	    // resetting this eagerly is always safe, mirroring `PhotoEntryCubit.
439	    // cancel()`'s own `_picking = false` reset.
440	    _stopping = false;
441	    final current = state;
442	    if (current is AudioRecording) {
443	      _elapsedTimer?.cancel();
444	      await _safeCancelRecorder();
445	      if (isClosed) {
446	        return;
447	      }
448	      emit(const AudioIdle());
449	    } else if (current is AudioProcessing) {
450	      // The recorder itself is already stopped by the time this state is
451	      // reached (`stopRecording` stops it before emitting `AudioProcessing`)
452	      // — only resetting the cubit's own state is left, so the pending
453	      // `_transcribe` continuation's own `state is! AudioProcessing` guard
454	      // (above) drops its result instead of resurrecting this flow. Review
455	      // finding: the already-recorded file is abandoned for good at this
456	      // point (nothing will ever retry it), so it must be deleted here —
457	      // the other orphan-file case `_micRecorder.cancel()` above already
458	      // handles on its own.
459	      unawaited(_deleteRecordingFile(current.path));
460	      emit(const AudioIdle());
461	    } else if (discardPreserved) {
462	      final path = switch (current) {
463	        AudioTranscribed(path: final p) => p,
464	        AudioError(path: final p) => p,
465	        _ => null,
466	      };
467	      if (path != null) {
468	        unawaited(_deleteRecordingFile(path));
469	      }
470	    }
471	  }
472	
473	  /// Best-effort `_micRecorder.cancel()` — a thrown `PlatformException`
474	  /// here (Review finding) must never escape uncaught, since both call
475	  /// sites (above, and [startRecording]'s own abandon-on-generation-
476	  /// mismatch branch) call this fire-and-forget.
477	  Future<void> _safeCancelRecorder() async {
478	    try {
479	      await _micRecorder.cancel();
480	    } catch (_) {
481	      // Best-effort — nothing in the UI depends on this succeeding.
482	    }
483	  }
484	
485	  /// I/O matrix's "Happy path"/"Save fails" rows: fires `POST /entries`
486	  /// with `source: audio` and `mediaDurationSeconds` for the current
487	  /// transcribed text. Mirrors `TextEntryCubit.save()`'s `isClosed`/
488	  /// no-double-submit guards exactly (Boundaries).
489	  ///
490	  /// Review finding: also callable from an [AudioError] save failure
491	  /// (non-null [AudioError.text]) — `_AudioErrorView`'s non-retry branch
492	  /// re-renders the editable field and calls this same method for its
493	  /// "Salvar" button, but the original guard only matched
494	  /// [AudioTranscribed], making a retry after any save failure a
495	  /// permanent no-op.
496	  Future<void> save() async {
497	    final current = state;
498	    final String path;
499	    final int durationSeconds;
500	    final String text;
501	    if (current is AudioTranscribed && !current.saving) {
502	      path = current.path;
503	      durationSeconds = current.durationSeconds;
504	      text = current.text.trim();
505	    } else if (current is AudioError &&
506	        current.text != null &&
507	        current.path != null &&
508	        current.durationSeconds != null) {
509	      path = current.path!;
510	      durationSeconds = current.durationSeconds!;
511	      text = current.text!.trim();
512	    } else {
513	      return;
514	    }
515	    if (text.isEmpty) {
516	      return;
517	    }
518	    emit(
519	      AudioTranscribed(
520	        path: path,
521	        durationSeconds: durationSeconds,
522	        text: text,
523	        saving: true,
524	      ),
525	    );
526	    final result = await _repository.create(
527	      content: text,
528	      source: EntrySource.audio,
529	      mediaDurationSeconds: durationSeconds,
530	    );
531	    // Mirrors `TextEntryCubit.save()`'s own `isClosed` guard — this
532	    // cubit's `close()` can race the awaited call above (e.g. the modal's
533	    // barrier is dismissed mid-save).
534	    if (isClosed) {
535	      return;
536	    }
537	    result.match(
538	      (failure) => emit(
539	        AudioError(
540	          path: path,
541	          durationSeconds: durationSeconds,
542	          message: failure.message,
543	          text: text,
544	        ),
545	      ),
546	      (_) {
547	        // Review finding: the recorded temp file was never deleted after
548	        // a successful save — fire-and-forget, a deletion failure must
549	        // never block the modal from closing.
550	        unawaited(_deleteRecordingFile(path));
551	        emit(const AudioSaved());
552	      },
553	    );
554	  }
555	
556	  /// Best-effort cleanup for a temp recording file this cubit is done
557	  /// with (saved successfully, or abandoned for good by [cancel] mid-
558	  /// processing) — deletion failures are swallowed since nothing in the
559	  /// UI depends on this succeeding (Review finding: previously never
560	  /// called at all, leaking a `.wav` file per recording indefinitely).
561	  Future<void> _deleteRecordingFile(String path) async {
562	    try {
563	      await File(path).delete();
564	    } catch (_) {
565	      // Best-effort — a missing/already-deleted file, or a transient
566	      // disk error, is never worth surfacing to the user.
567	    }
568	  }
569	
570	  @override
571	  Future<void> close() {
572	    _elapsedTimer?.cancel();
573	    return super.close();
574	  }
575	}
